import cv2, numpy as np, json
# exemplar source (file, x,y,r) in 2x images
spec={
'Vayne':('work/lane_0090.png',187,211,55),'Sejuani':('work/lane_0090.png',592,212,55),'Garen':('work/lane_0090.png',165,301,52),'Zac':('work/lane_0090.png',242,592,60),'Ahri':('work/lane_0090.png',686,659,54),'Zyra':('work/lane_0090.png',793,626,54),\"Kai'Sa\":('work/lane_0090.png',965,1250,54),'Thresh':('work/lane_0090.png',1003,1205,55),'Lillia':('work/lane_0300.png',1155,1225,58),'Taliyah':('work/lane_0300.png',1161,1138,55)}
def normcrop(im,x,y,r):
 rr=int(r*.78); c=im[y-rr:y+rr,x-rr:x+rr]
 return cv2.resize(c,(72,72))
def feat(c):
 hsv=cv2.cvtColor(c,cv2.COLOR_BGR2HSV); mask=np.zeros((72,72),np.uint8);cv2.circle(mask,(36,36),34,255,-1)
 h=cv2.calcHist([hsv],[0,1],mask,[36,32],[0,180,0,256]);cv2.normalize(h,h);return h
refs={}
for n,(f,x,y,r) in spec.items(): refs[n]=feat(normcrop(cv2.imread(f),x,y,r))
cap=cv2.VideoCapture('minimap_vod.mp4');dur=int(cap.get(cv2.CAP_PROP_FRAME_COUNT)/cap.get(cv2.CAP_PROP_FPS))+1
rows=[]
for s in range(dur):
 cap.set(cv2.CAP_PROP_POS_MSEC,s*1000);ok,im=cap.read()
 if not ok: continue
 big=cv2.resize(im,(1400,1384));gray=cv2.cvtColor(big,cv2.COLOR_BGR2GRAY)
 cs=cv2.HoughCircles(gray,cv2.HOUGH_GRADIENT,1.2,42,param1=100,param2=34,minRadius=45,maxRadius=66)
 best={n:-1 for n in refs}; loc={n:None for n in refs}
 if cs is not None:
  for x,y,r in np.round(cs[0]).astype(int):
   if x-r<0 or y-r<0 or x+r>=1400 or y+r>=1384: continue
   c=normcrop(big,x,y,r); f=feat(c)
   for n,rf in refs.items():
    sc=cv2.compareHist(f,rf,cv2.HISTCMP_CORREL)
    if sc>best[n]:best[n]=sc;loc[n]=(int(x),int(y),int(r))
 rows.append({'s':s,'score':best,'loc':loc})
 if s%300==0: print(s)
open('work/presence.json','w').write(json.dumps(rows))
# print low runs threshold .45
for n in refs:
 vals=[r['score'][n] for r in rows]; missing=[v<.45 for v in vals]; runs=[];st=None
 for i,m in enumerate(missing+[False]):
  if m and st is None:st=i
  if not m and st is not None:
   if i-st>=3:runs.append((st,i-1,round(min(vals[st:i]),2),round(max(vals[st:i]),2)))
   st=None
 print(n,runs)
